     mp(5)*(-m(5)/a)*drdx421(21,15,xyz,r)+mp(4)*(-m(4)/a)*drdx421(21,18,xyz,r)+mp(2)*(-m(2)/a)*drdx421(21,20,xyz,r)+&
    mp(1)*(-m(1)/a)*drdx421(21,21,xyz,r)

    return
  end subroutine deriv_rev421

end module bemsa421
